; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_nx_palentry:		; sub palentry (asm keyword), Nx.cls line 83
            pop hl
            ld a, (hl)
            and 3
            rlca
            rlca
            rlca
            rlca
            ld d, a                 ; palette select, bits 6-4
            pop hl
            ld e, (hl)              ; index
            pop hl
            ld l, (hl)              ; colour
            ld bc, #243B
            ld a, #43
            out (c), a
            inc b
            out (c), d
            dec b
            ld a, #40
            out (c), a
            inc b
            out (c), e
            dec b
            ld a, #41
            out (c), a
            inc b
            out (c), l
            dec b
            ld a, #43
            out (c), a
            inc b
            xor a
            out (c), a
			ret			; end of #asm

fn_graphics_line:		; sub line (asm keyword), Graphics.cls line 13
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_x0), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_y0), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_x1), de
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld (gfx_y1), de
            ld (gfx_sp), sp
            ld sp, (ntc_csp)
            call gfx_line
            ld sp, (gfx_sp)
			ret			; end of #asm

fn_graphics_pen:		; sub pen (asm keyword), Graphics.cls line 67
            pop hl
            ld a, (hl)
            ld (gfx_pen), a
			ret			; end of #asm

fn_graphics_clip:		; sub clip (asm keyword), Graphics.cls line 77
            pop hl
            ld a, (hl)
            or a
            jr z, fn_graphics_clip_cl0
            ld a, 1
fn_graphics_clip_cl0:
            ld (gfx_clip), a
			ret			; end of #asm

fn_keys_down:		; function down (asm keyword), Keys.cls line 77
            pop hl
            ld e, (hl)
            inc hl
            ld d, (hl)
            ld a, d
            or a
            jr nz, fn_keys_down_kdno
            ld a, e
            cp 64
            jr nc, fn_keys_down_kdno
            and 7
            cp 5
            jr nc, fn_keys_down_kdno
            inc a
            ld d, a                 ; D = bit + 1
            ld a, e
            rrca
            rrca
            rrca
            and 7
            inc a                   ; A = half row + 1
            ld b, a
            ld a, #7F
fn_keys_down_kdrow:
            rlca                    ; #FE for half row 0, #FD 1 ... #7F 7
            djnz fn_keys_down_kdrow
            ld b, a
            ld c, #FE
            in a, (c)
            ld b, d
fn_keys_down_kdbit:
            rrca
            djnz fn_keys_down_kdbit
            ld de, 0
            jr c, fn_keys_down_kdset               ; 1 = not pressed
            dec de
            jr fn_keys_down_kdset
fn_keys_down_kdno:
            ld de, 0
fn_keys_down_kdset:
            pop hl
            ld (hl), e
            inc hl
            ld (hl), d
			ret			; end of #asm


